import {el,button,link,announce,focusHeading,practiceFrame,optionsList,recommendations} from './ui.js';
export function resultBand(score){return score<=4?'Beginner':score<=7?'Developing Awareness':'Cyber Aware';}
export function createQuiz(questions,scams,openArticle){let index=0;let answers=[];let pending=null;let finished=false;let host;
function render(shouldFocus=false){if(finished){summary();return;}const q=questions[index];const answer=answers[index];const body=practiceFrame(host,index+1,questions.length,'SAFETY QUIZ');body.append(el('span','tag','A little knowledge goes a long way'),el('h2','',q.question));body.append(optionsList(q.options,answer??pending,answer?q.correctOptionId:null,id=>{pending=id;render();host.querySelectorAll('.option')[q.options.findIndex(o=>o.id===id)].focus();}));if(answer){const correct=answer===q.correctOptionId;const feedback=el('div',`feedback ${correct?'':'risky'}`);feedback.setAttribute('role','status');feedback.append(el('h3','',correct?'Correct. Keep that habit.':'Here is what to remember.'),el('p','',q.explanation));const selected=q.options.find(o=>o.id===answer);if(selected?.rationale)feedback.append(el('p','choice-reason','Your response: '+selected.rationale));body.append(feedback);}const bottom=el('div','practice-bottom');const back=button('← Back','button secondary',()=>{index--;pending=null;render(true);});back.disabled=index===0;bottom.append(back);const next=button(answer?(index===questions.length-1?'See my results →':'Next question →'):'Submit answer','button',()=>{if(answers[index]){if(index===questions.length-1)finished=true;else index++;pending=null;render(true);}else if(pending){answers[index]=pending;render();announce(answers[index]===q.correctOptionId?'Correct answer.':'Answer submitted. Read the correct answer and explanation.');}});next.disabled=!answer&&!pending;bottom.append(next);body.append(bottom,el('p','quiz-note','Answers lock after submission. You can go back to review any completed question.'),button('Restart quiz','reset-button',restart));if(shouldFocus)focusHeading(host);}
function summary(){host.replaceChildren();const score=questions.reduce((n,q,i)=>n+(answers[i]===q.correctOptionId?1:0),0);const box=el('div','practice-shell summary');box.append(el('span','tag green','Quiz complete'),el('h2','',resultBand(score)));const n=el('div','score-display',String(score));n.append(el('span','',' / 10'));box.append(n,el('p','','This result reflects your performance on this quiz, not a guarantee of real-world security. Keep pausing, checking and using official channels.'));const missed=questions.filter((q,i)=>answers[i]!==q.correctOptionId);box.append(el('h3','',missed.length?'Your next learning steps':'Great work. Keep practising.'));recommendations(box,(missed.length?missed:questions.slice(0,3)).map(q=>q.topic),scams,openArticle);const actions=el('div','actions');actions.append(button('Restart quiz','button',restart),link('Explore the library','#library','button secondary'));box.append(actions);questions.forEach((q,i)=>{const details=el('details','review');const answer=q.options.find(o=>o.id===q.correctOptionId);details.append(el('summary','',`${answers[i]===q.correctOptionId?'✓':'↺'} Question ${i+1}: ${q.question}`),el('p','',`Correct answer: ${answer.text}`),el('p','',q.explanation));box.append(details);});host.append(box);focusHeading(host);}
function restart(){index=0;answers=[];pending=null;finished=false;render(true);announce('Quiz restarted. Previous responses cleared.');}
return{mount(container){host=container;render();},reset(){index=0;answers=[];pending=null;finished=false;}};}
